python3 << 'EOF'
import json, os, glob

# Get only feishu user messages (humans)
dirs = glob.glob(os.path.expanduser('~/.claude-account-*/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-4-projects-trace-verdict-study--claude-sessions-director-*/'))
user_msgs = []
seen_text = set()
for d in dirs:
    for f in glob.glob(os.path.join(d, '*.jsonl')):
        try:
            with open(f) as fp:
                for line in fp:
                    if '飞书用户' not in line:
                        continue
                    try:
                        j = json.loads(line)
                    except:
                        continue
                    msg = j.get('message')
                    if not isinstance(msg, dict):
                        continue
                    content = msg.get('content')
                    text = ''
                    if isinstance(content, str):
                        text = content
                    elif isinstance(content, list):
                        for c in content:
                            if isinstance(c, dict) and c.get('type') == 'text':
                                text += c.get('text', '')
                    if '飞书用户' in text:
                        key = text[:200]
                        if key not in seen_text:
                            seen_text.add(key)
                            user_msgs.append((j.get('timestamp',''), text[:800]))
        except Exception:
            pass

user_msgs.sort()
print(f'Unique feishu user messages: {len(user_msgs)}')
# Group by user
import re
users = {}
for ts, t in user_msgs:
    m = re.search(r'飞书用户 ([^\(]+)', t)
    if m:
        u = m.group(1).strip()
        users.setdefault(u, []).append((ts, t))

for u, msgs in users.items():
    print(f'\n=== USER: {u} ({len(msgs)} messages) ===')
    print('  first:', msgs[0][0])
    print('  last:', msgs[-1][0])

# Show all messages sorted by time (for full timeline)
print('\n=== ALL MESSAGES TIMELINE ===')
for ts, t in user_msgs:
    # extract user
    m = re.search(r'飞书用户 ([^\(]+)\(', t)
    u = m.group(1).strip() if m else '?'
    # extract message body
    m2 = re.search(r'\)\]: (.*)', t, re.DOTALL)
    body = m2.group(1).strip()[:300] if m2 else t[:300]
    print(f'[{ts}] [{u}] {body[:250]}')
EOF
